//! Tryndamere. Fury (his crit chance) is generated by basic attacks (+5, or
//! +10 on a crit) and by Spinning Slash hits, and decays only after 8 s of
//! inactivity that never occurs in this fight. Undying Rage opens the fight
//! for its instant Fury burst; Spinning Slash goes out on cooldown, its
//! on-hit crits refunding part of its cooldown; Bloodlust and Mocking Shout
//! are never cast (see kit notes).

use crate::fight::{shave, Driver, Engine, Events, Kind, St};
use crate::fx::*;
use crate::kit::Kit;
use crate::num::*;
use crate::sheet::Sheet;

/// Spinning Slash is cast, on cooldown (shortened by on-hit crit refunds).
const EV_E_CAST: u8 = 0;

#[derive(Clone, Debug, PartialEq)]
pub struct GenDriver {
    ranks: Ranks,
    attack_range: f64,
    windup_fraction: f64,
    fury_per_attack: f64,
    fury_per_crit: f64,
    max_fury: f64,
    crit_pct_per_fury: f64,
    e_cd: f64,
    e_dmg: f64,
    e_fury_gain: f64,
    e_refund_s: f64,
    r_fury_gain: f64,
    src_p_crit: SourceId,
    s: State,
    s0: State,
}

/// Everything a fight moves: the Fury pool and Spinning Slash's ready time.
#[derive(Clone, Copy, Debug, PartialEq)]
struct State {
    fury: f64,
    e_ready: f64,
}

impl Driver for GenDriver {
    fn new(kit: &Kit, sheet: &Sheet, _level: i64, ranks: Ranks, _prestacked: bool)
        -> Result<Self, String> {
        let state = State { fury: 0.0, e_ready: 0.0 };
        Ok(GenDriver {
            ranks,
            attack_range: sheet.base_attack_range,
            windup_fraction: kit.windup_fraction.ok_or("tryndamere kit needs attack.windupFraction")?,
            fury_per_attack: kit.num("gen.P.furyPerAttack")?,
            fury_per_crit: kit.num("gen.P.furyPerCrit")?,
            max_fury: kit.num("gen.P.maxFury")?,
            crit_pct_per_fury: kit.num("gen.P.critChancePctPerFury")?,
            e_cd: kit.at_rank("abilities.E.cooldownS", ranks.e)?,
            e_dmg: kit.hit("gen.E.damage", ranks.e, sheet)?,
            e_fury_gain: kit.num("gen.E.furyPerChampionHit")?,
            e_refund_s: kit.num("gen.E.champCdRefundS")?,
            r_fury_gain: kit.at_rank("gen.R.furyGain", ranks.r)?,
            src_p_crit: intern("P crit bonus"),
            s: state,
            s0: state,
        })
    }

    fn reset(&mut self) {
        self.s = self.s0;
    }

    fn ranged(&self) -> bool {
        false
    }

    fn attack_range(&self) -> f64 {
        self.attack_range
    }

    fn shave_cooldowns(&mut self, st: &mut St, t: f64, factor: f64) {
        shave(&mut st.q_ready, t, factor);
        shave(&mut self.s.e_ready, t, factor);
    }

    fn after_attack(&mut self, e: &mut Engine) {
        // Item crit chance is already priced into the engine's own attack
        // damage; Fury adds crit chance on top of that, additively, capped
        // at 100% total. Only the incremental part is added here.
        let item_crit = e.p.sheet.crit_chance / 100.0;
        let fury_crit = pymin(self.s.fury, self.max_fury) * self.crit_pct_per_fury / 100.0;
        let combined = pymin(item_crit + fury_crit, 1.0);
        let extra_frac = pymax(combined - item_crit, 0.0);
        let crit_mult = e.p.sheet.crit_damage / 100.0;
        let extra_dmg = e.p.ad * extra_frac * (crit_mult - 1.0);
        if extra_dmg > 0.0 {
            e.deal(extra_dmg, DType::Physical, self.src_p_crit, false, false, 1.0);
        }

        // Spinning Slash's cooldown is refunded, in expectation, by the
        // same combined crit chance (a champion-target refund, since the
        // dummy counts as a champion).
        if self.ranks.e > 0 {
            self.s.e_ready = pymax(e.st.t, self.s.e_ready - combined * self.e_refund_s);
        }

        // Fury gained is, in expectation, the base gain plus the extra a
        // critical strike gives, weighted by the same combined crit chance.
        let gain = self.fury_per_attack + (self.fury_per_crit - self.fury_per_attack) * combined;
        self.s.fury = pymin(self.s.fury + gain, self.max_fury);
    }

    fn q_at(&self, _e: &Engine) -> f64 {
        INF
    }

    fn cast_q(&mut self, _e: &mut Engine) {
        // Bloodlust is never cast: see kit notes.
    }

    fn cast_r(&mut self, e: &mut Engine) {
        if self.ranks.r == 0 {
            return;
        }
        self.s.fury = pymin(self.s.fury + self.r_fury_gain, self.max_fury);
        e.prime_spellblade();
    }

    fn events(&self, e: &Engine, out: &mut Events) -> usize {
        let mut n = 0;
        if self.ranks.e > 0 {
            out[n] = (pymax(self.s.e_ready, e.st.t), Kind::Ev(EV_E_CAST));
            n += 1;
        }
        n
    }

    fn on_event(&mut self, e: &mut Engine, kind: Kind) {
        match kind {
            Kind::Ev(EV_E_CAST) => {
                e.deal(self.e_dmg, DType::Physical, SRC_E, false, true, 1.0);
                e.ability_cast_proc();
                e.eclipse_hit();
                e.prime_spellblade();
                self.s.fury = pymin(self.s.fury + self.e_fury_gain, self.max_fury);
                self.s.e_ready = e.st.t + e.basic_cd(self.e_cd);
            }
            other => panic!("unhandled event {other:?}"),
        }
    }
}
